from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def evict_expired(key, t):
        if key in cache:
            value, wt = cache[key]
            if t >= wt + ttl:
                del cache[key]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            evict_expired(key, t)
            if key in cache:
                del cache[key]
            elif len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = (value, t)
        else:
            _, t, key = op
            evict_expired(key, t)
            if key in cache:
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

